# Lesson 2, parts 5 and 6, sources.
# Figures of the math exercises are checked here, so a typo stops the build.
assert max(80 - 72, 0) - 5 == 3 and 80 - 5 == 75 and 80 - 5 - 12 == 63
assert round(800000 * 3.85) == 3080000 and round(800000 * 3.62) == 2896000 and round(800000 * (3.85 - 3.62)) == 184000
assert (60 - 70) + 4 == -6 and (4420 - 4300 - 40) * 50 * 3 == 12000 and 40 * 50 * 3 == 6000
assert round((3.60 - 3.40 - 0.05) * 10000 * 10) == 15000
assert 3000 * 50 == 150000 and 150000 / 15000 == 10 and 150000 * 0.01 == 1500

# ================================================================ part 6
opener(5, 'תרגילים מסכמים למפגש 2', 'שאלת החלק: האם אתם יודעים לבנות את החישוב לבד?',
       ['תרגילים מתמטיים, עם בדיקה אוטומטית', 'תרגילים בגיליון Excel שבתוך השקף', 'בכל תרגיל: רמז, תזכורת נוסחה, פתרון חלקי ופתרון מלא'], 25)

SOLVE('t-1', 'תרגיל 1: Long Put', 'תרגיל 1: קונה אופציית מכר (Long Put)',
      'משקיע קנה אופציית מכר (Put) על מניה: מחיר מימוש (K) 80, פרמיה (p) 5, מכפיל (Multiplier) 1.',
      [('א. הרווח, אם המחיר בפקיעה 72', 3, 0.001), ('ב. נקודת האיזון (Break-even)', 75, 0.001), ('ג. המחיר שבו הרווח בדיוק 12', 63, 0.001), ('ד. הרווח המרבי', 75, 0.001)],
      ['תזרים ב-Put: $max(K − S_{T}, 0)$.', 'בנקודת האיזון הרווח אפס.', 'הרווח מרבי כשהמניה צונחת לאפס.'], 'רווח = $max(K − S_{T}, 0) − p$. נקודת איזון: $K − p$.',
      ['<b>א.</b> $max(80 − 72, 0) − 5 = 3$', '<b>ב.</b> $80 − 5 = 75$', '<b>ג.</b> $80 − S_{T} − 5 = 12$, ולכן $S_{T} = 63$', '<b>ד.</b> $80 − 0 − 5 = 75$'])
SOLVE('t-2', 'תרגיל 2: Short Call', 'תרגיל 2: כותב אופציית רכש (Short Call)',
      'משקיעה כתבה אופציית רכש (Call): מחיר מימוש (K) 60, היא קיבלה פרמיה (c) 4, מכפיל (Multiplier) 1.',
      [('א. התוצאה, אם המחיר בפקיעה 70', -6, 0.001), ('ב. התוצאה, אם המחיר בפקיעה 55', 4, 0.001), ('ג. נקודת האיזון (Break-even)', 64, 0.001), ('ד. הרווח המרבי', 4, 0.001)],
      ['הכותבת מקבלת את הפרמיה בכל מקרה.', 'אם הקונה מממש, היא מוכרת ב-K מה ששווה יותר.'], 'רווח = $c − max(S_{T} − K, 0)$. נקודת איזון: $K + c$.',
      ['<b>א.</b> $4 − (70 − 60) = −6$', '<b>ב.</b> לא ממומשת: $4 − 0 = 4$', '<b>ג.</b> $60 + 4 = 64$', '<b>ד.</b> הפרמיה: 4'])
SOLVE('t-4', 'תרגיל 3: מכפיל במדד', 'תרגיל 3: Call על מדד, עם מכפיל (Multiplier)',
      'קניתם 3 אופציות רכש (Call) על מדד: מחיר מימוש (K) 4,300, פרמיה (c) 40 נקודות, מכפיל (Multiplier) 50 ש״ח. המדד בפקיעה 4,420.',
      [('א. העלות היום, ש״ח', 6000, 0.5), ('ב. התזרים בפקיעה, בנקודות, לאופציה', 120, 0.001), ('ג. הרווח, ש״ח, לכל שלוש האופציות', 12000, 0.5), ('ד. נקודת האיזון, במדד', 4340, 0.001)],
      ['קודם בנקודות, לאופציה אחת. רק בסוף כופלים במכפיל ובמספר האופציות.'], 'רווח (ש״ח) = ($max(S_{T} − K, 0) − c$) × מכפיל × מספר.',
      ['<b>א.</b> $40 × 50 × 3 = 6,000$', '<b>ב.</b> $4,420 − 4,300 = 120$', '<b>ג.</b> $(120 − 40) × 50 × 3 = 12,000$', '<b>ד.</b> $4,300 + 40 = 4,340$'])
SOLVE('t-5', 'תרגיל 4: Put על דולר', 'תרגיל 4: Put על הדולר, מכפיל 10,000',
      'קניתם 10 אופציות מכר (Put) על הדולר: מחיר מימוש (K) 3.60, פרמיה (p) 0.05 ש״ח לדולר, מכפיל (Multiplier) 10,000. השער בפקיעה 3.40.',
      [('א. העלות היום, ש״ח', 5000, 0.5), ('ב. הרווח, ש״ח', 15000, 0.5), ('ג. נקודת האיזון, שער', 3.55, 0.0001)],
      ['התזרים לדולר אחד: $3.60 − 3.40$.', 'בסוף כופלים ב-10,000 וב-10.'], 'רווח (ש״ח) = ($max(K − S_{T}, 0) − p$) × מכפיל × מספר.',
      ['<b>א.</b> $0.05 × 10,000 × 10 = 5,000$', '<b>ב.</b> $(3.60 − 3.40 − 0.05) × 10,000 × 10 = 15,000$', '<b>ג.</b> $3.60 − 0.05 = 3.55$'])
SOLVE('t-6', 'תרגיל 5: מנוף', 'תרגיל 5: מנוף (Leverage) בחוזה עתידי (Futures)',
      'קניתם (Long) חוזה עתידי (Futures) אחד על מדד ברמה של 3,000 נקודות, מכפיל (Multiplier) 50 ש״ח. הפקדתם ביטחונות (Margin) של 15,000 ש״ח. המדד עלה ב-1%.',
      [('א. החשיפה, ש״ח', 150000, 1), ('ב. המנוף', 10, 0.001), ('ג. הרווח, ש״ח', 1500, 0.5), ('ד. התשואה על הביטחונות, %', 10, 0.001)],
      ['חשיפה: מדד × מכפיל.', 'מנוף: חשיפה ÷ ביטחונות.'], 'תשואה על הביטחונות = רווח ÷ ביטחונות.',
      ['<b>א.</b> $3,000 × 50 = 150,000$', '<b>ב.</b> $150,000 ÷ 15,000 = 10$', '<b>ג.</b> $150,000 × 1% = 1,500$', '<b>ד.</b> $1,500 ÷ 15,000 = 10%$'])

OPTX('e-1', 'תרגיל 6: Long Call באקסל', '<b>תרגיל 6.</b> קונה אופציית רכש (Long Call): מחיר מימוש (K) 105, פרמיה (c) 4. כתבו נוסחאות לתזרים ולרווח, וגררו.', 105, 4, 'call', 1, [85, 95, 105, 115, 125], False, -10, 25, [-10, 0, 10, 20], [85, 95, 105, 115, 125])
OPTX('e-2', 'תרגיל 7: Short Put באקסל', '<b>תרגיל 7.</b> כותב אופציית מכר (Short Put): מחיר מימוש (K) 40, הוא קיבל פרמיה (p) 3. כתבו נוסחאות, וגררו. הקפידו על הסימן.', 40, 3, 'put', -1, [25, 30, 35, 40, 45, 50], False, -15, 10, [-15, -10, -5, 0, 5, 10], [25, 30, 35, 40, 45, 50])
OPTX('e-3', 'תרגיל 8: Short Call באקסל', '<b>תרגיל 8.</b> כותב אופציית רכש (Short Call): מחיר מימוש (K) 75, הוא קיבל פרמיה (c) 5. כתבו נוסחאות, וגררו.', 75, 5, 'call', -1, [60, 70, 75, 80, 90], False, -15, 10, [-15, -10, -5, 0, 5, 10], [60, 70, 75, 80, 90])

S('s-sum', 'סיכום השיעור', 'סיכום השיעור, בשבעה משפטים',
  '<ol class="steps two">' + ''.join(f'<li><span>{TX(x)}</span></li>' for x in [
      'באופציה (Option) רק הכותב (Short) מחויב. הקונה (Long) מחזיק בזכות, ומשלם עליה פרמיה (Premium).', 'קודם תזרים (Payoff), אחר כך רווח (P&L), ובסוף בכסף: מכפיל (Multiplier) ומספר חוזים.',
      'אופציה אירופאית (European) ממומשת רק בפקיעה, ואמריקאית (American) בכל יום עד הפקיעה. זכות נוספת לא מורידה שווי.', 'בעסקת החלפה (Swap) מחליפים תזרימים בכמה מועדים, למשל ריבית משתנה בריבית קבועה.',
      'מגדר (Hedger) קונה ודאות, לא תוצאה טובה יותר. ספקולנט (Speculator) קונה מנוף (Leverage), לשני הכיוונים.', 'בורסה (Exchange) מספקת אחידות וערבות, ושוק מעבר לדלפק (OTC) מספק התאמה עם סיכון צד נגדי (Counterparty risk).', 'בחברת התעופה, יחס הגידור (Hedge ratio) קובע איזה חלק מההוצאה קבוע, ואיזה חלק נשאר חשוף למחיר הדלק.']) + '</ol>', kick='סיכום')

